#!/usr/bin/env bash
# step80 — WhatsApp module fix: never fabricate a phone from a LID.
# - lib/waidentity.js: normalizePhoneE164 rejects @lid; identifiersFrom only
#   derives a phone from a real PN JID.
# - routes/whatsapp.js: webhook classifies raw jid into lid vs pn (no more
#   LID-as-PN), and the verify page shows the profile number as fallback.
# - views/account/whatsapp.ejs: truthful "linked" display when no PN captured.
# - cleanup migration: scrub fabricated +<lid> phone + bogus aliases.
# Idempotent; rolls back the 3 files it overwrites.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step80-$TS
mkdir -p "$BAK/lib" "$BAK/routes" "$BAK/views/account"
cp "$APP/lib/waidentity.js" "$BAK/lib/waidentity.js"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
cp "$APP/views/account/whatsapp.ejs" "$BAK/views/account/whatsapp.ejs"
restore(){ echo "!! rollback"; cp "$BAK/lib/waidentity.js" "$APP/lib/waidentity.js"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; cp "$BAK/views/account/whatsapp.ejs" "$APP/views/account/whatsapp.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite fixed files"
base64 -d > "$APP/lib/waidentity.js" <<'B64'

B64
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64
base64 -d > "$APP/views/account/whatsapp.ejs" <<'B64'

B64

echo "==> node --check + ejs compile"
node --check "$APP/lib/waidentity.js"
node --check "$APP/routes/whatsapp.js"
node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$APP/views/account/whatsapp.ejs','utf8'),{filename:'x'});console.log('   views compile OK');"

echo "==> cleanup: scrub fabricated phone + bogus aliases"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  const a = await p.query("DELETE FROM whatsapp_identity_aliases WHERE identifier_type IN ('PN_JID','PHONE_E164') AND lower(identifier_value) LIKE '%@lid%'");
  const u = await p.query("UPDATE whatsapp_identities SET current_phone_e164=NULL, phone_source=NULL, current_phone_verified=false WHERE current_phone_e164 IS NOT NULL AND canonical_lid IS NOT NULL AND current_phone_e164 = ('+'||canonical_lid)");
  const h = await p.query("DELETE FROM whatsapp_phone_history WHERE phone_e164 IN (SELECT ('+'||canonical_lid) FROM whatsapp_identities WHERE canonical_lid IS NOT NULL)");
  console.log('   removed bogus aliases: '+a.rowCount+' | cleared fabricated phone on identities: '+u.rowCount+' | cleaned phone_history: '+h.rowCount);
  const idn = (await p.query('SELECT id, canonical_lid, current_phone_e164, phone_source FROM whatsapp_identities ORDER BY id DESC LIMIT 1')).rows[0];
  if(idn) console.log('   latest identity now -> lid='+idn.canonical_lid+' phone='+idn.current_phone_e164+' source='+idn.phone_source);
  await p.end();
})().catch(e=>{ console.error('CLEANUP FAIL: '+e.message); process.exit(1); });
NODE

echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
C1=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/account/whatsapp || true)
[ "$C1" = "302" ] || { echo "!! /account/whatsapp should redirect to login (got $C1)"; false; }
trap - ERR
echo "==> step80 OK — LID-as-phone bug fixed + data cleaned. Backup: $BAK"
echo "   Dashboard will now show your real profile number (923141892712), not the LID."
echo "   Then re-run the bot update:  (two lines)"
echo "     git pull"
echo "     bash step79.sh"
